from base import *
G = 8
L, P = (1440, 900), (390, 844)
def lpage(name, title, on, crumb, h1, right, main, shows, route, ms, pill_=''):
    body = lbar('manager', on) + cp(crumb, h1, right, pill_) + f'\n  <main class="page" style="flex-direction: row; gap: 20px">{main}</main>'
    page(name, *L, title, body, G, 'Manager', shows, route, ms)
def ppage(name, title, head, main, on, shows, route, ms, foot=''):
    f = f'<footer class="foot">{foot}</footer>' if foot else navbar('manager', on, True)
    page(name, *P, title, head + f'<main class="body">{main}</main>' + f, G, 'Manager', shows, route, ms)
def table(heads, rows, sel=None, cls='dt'):
    th = ''.join(f'<th{" class=\"num\"" if h.startswith("#") else ""}>{h.lstrip("#")}</th>' for h in heads)
    tr = ''.join(f'<tr{" class=\"sel\"" if r[0] == sel else ""}>' + ''.join(f'<td{" class=\"num\"" if heads[i].startswith("#") else ""}>{c}</td>' for i, c in enumerate(r)) + '</tr>' for r in rows)
    return f'<div class="card" style="overflow: hidden"><table class="{cls}"><thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table></div>'
def side(c, w=420): return f'<aside class="vstack g16" style="width: {w}px; flex: none">{c}</aside>'
def card(c, pad='16px 20px'): return f'<div class="card" style="padding: {pad}">{c}</div>'
def tiles(items): return '<div class="card"><div class="tilerow" style="grid-template-columns: repeat(' + str(len(items)) + ', minmax(0, 1fr))">' + ''.join(f'<div class="stat"><span class="t-sup muted">{l}</span><b>{v}</b>{f"<span class=\"t-sup muted\">{s}</span>" if s else ""}</div>' for l, v, s in items) + '</div></div>'

